import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String filterExpr = req.getParameter("filter");

        if (reportId == null || reportId.isEmpty()) {
            resp.sendError(400, "Missing report id");
            return;
        }

        // Validate report ID is numeric
        if (!reportId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid report id format");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // First get report metadata using parameterized query
            PreparedStatement metaStmt = conn.prepareStatement(
                "SELECT name, owner, created_at, template FROM reports WHERE id = ?");
            metaStmt.setInt(1, Integer.parseInt(reportId));
            ResultSet metaRs = metaStmt.executeQuery();

            if (!metaRs.next()) {
                resp.sendError(404, "Report not found");
                return;
            }

            String reportName = metaRs.getString("name");
            String owner = metaRs.getString("owner");
            String template = metaRs.getString("template");

            // Build data query with optional filter
            // The filter allows power users to add custom WHERE clauses
            String dataQuery = "SELECT * FROM report_data_" + reportId;
            if (filterExpr != null && !filterExpr.isEmpty()) {
                // Basic sanitization - remove comments and semicolons
                String sanitized = filterExpr.replaceAll("--", "")
                                            .replaceAll(";", "")
                                            .replaceAll("/\\*.*?\\*/", "");
                dataQuery += " WHERE " + sanitized;
            }

            Statement dataStmt = conn.createStatement();
            ResultSet dataRs = dataStmt.executeQuery(dataQuery);

            ResultSetMetaData rsMeta = dataRs.getMetaData();
            int colCount = rsMeta.getColumnCount();

            List<Map<String, Object>> rows = new ArrayList<>();
            while (dataRs.next()) {
                Map<String, Object> row = new LinkedHashMap<>();
                for (int i = 1; i <= colCount; i++) {
                    row.put(rsMeta.getColumnName(i), dataRs.getObject(i));
                }
                rows.add(row);
            }

            // Format output
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{\"report\":\"" + reportName + "\",");
            out.print("\"owner\":\"" + owner + "\",");
            out.print("\"rowCount\":" + rows.size() + ",");
            out.print("\"data\":[");
            for (int i = 0; i < rows.size(); i++) {
                if (i > 0) out.print(",");
                out.print(mapToJson(rows.get(i)));
            }
            out.print("]}");

        } catch (SQLException e) {
            resp.sendError(500, "Database error: " + e.getMessage());
        }
    }

    private String mapToJson(Map<String, Object> map) {
        StringBuilder sb = new StringBuilder("{");
        boolean first = true;
        for (Map.Entry<String, Object> entry : map.entrySet()) {
            if (!first) sb.append(",");
            sb.append("\"" + entry.getKey() + "\":");
            if (entry.getValue() == null) sb.append("null");
            else if (entry.getValue() instanceof Number) sb.append(entry.getValue());
            else sb.append("\"" + entry.getValue().toString().replace("\"", "\\\"") + "\"");
            first = false;
        }
        sb.append("}");
        return sb.toString();
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Delegate to GET for backward compatibility
        doGet(req, resp);
    }
}
